<script>
const metricsUrl=document.querySelector('[data-order-metrics]')?.dataset.orderMetrics;const clock=document.getElementById('pcClock');let elapsed=Number(clock?.dataset.elapsed||0),last=Date.now();const isPaused=@json((bool)$activePause);if(clock&&!isPaused){setInterval(()=>{let now=Date.now();elapsed+=(now-last)/1000;last=now;clock.textContent=fmt(elapsed)},1000)}function fmt(v){let n=Math.floor(v),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return [h,m,s].map(x=>String(x).padStart(2,'0')).join(':')}function addNewWorker(){let x=document.createElement('input');x.className='pc-field';x.name='workers[]';x.required=true;x.placeholder='Nombre del operario';x.style.marginBottom='8px';document.getElementById('newWorkers').appendChild(x)}
async function refreshMetrics(){if(!metricsUrl)return;try{let r=await fetch(metricsUrl,{headers:{'Accept':'application/json'}});if(!r.ok)return;let d=await r.json();let t=Number(d.theoretical),a=Number(d.actual);let e=document.getElementById('pcTheoretical');if(e)e.textContent=Math.round(t).toLocaleString('es-PE');e=document.getElementById('pcLiveTheoretical');if(e)e.textContent=Math.round(t).toLocaleString('es-PE')+' unidades';e=document.getElementById('pcActual');if(e)e.textContent=Math.round(a).toLocaleString('es-PE');e=document.getElementById('pcElapsed');if(e)e.textContent=fmt(d.seconds);let pct=Math.min(100,Number(@json((float)$production_order->target_quantity))>0?t/Number(@json((float)$production_order->target_quantity))*100:0);e=document.getElementById('pcPercent');if(e)e.textContent=pct.toFixed(1)+'%';e=document.getElementById('pcProgressBar');if(e)e.style.width=pct+'%'}catch(e){console.warn('No se pudo actualizar el seguimiento',e)}}if(metricsUrl)setInterval(refreshMetrics,15000);

</script>
